import type {
  PresentationDeck,
  PresentationRecord,
  PresentationSlide,
  PresentationSlideDefinition,
} from "./deck.ts";
import { createPresentationTopology } from "./topologyLayouts.ts";

function createSlideTopology(definition: PresentationSlideDefinition) {
  return createPresentationTopology(definition);
}

function normalizeContentMatch(value: string): string {
  return value
    .toLocaleLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, " ")
    .trim();
}

function getNodeContent(content: string, label: string, isRoot: boolean): string {
  const source = content.trim();
  if (!source || isRoot) return source;

  const decodeEntities = (value: string) => value
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&#39;/g, "'")
    .replace(/&quot;/g, '"');
  const stripTags = (value: string) => decodeEntities(value.replace(/<[^>]+>/g, " "));
  const target = normalizeContentMatch(label);
  const headingPattern = /<h([1-6])(?:\s[^>]*)?>([\s\S]*?)<\/h\1>/gi;
  const headings = [...source.matchAll(headingPattern)];
  const startHeading = headings.find((heading) =>
    normalizeContentMatch(stripTags(heading[2])).includes(target),
  );

  if (!startHeading || startHeading.index === undefined) return source;

  const level = Number(startHeading[1]);
  const endHeading = headings.find((heading) =>
    heading.index !== undefined &&
    heading.index > startHeading.index &&
    Number(heading[1]) <= level,
  );
  const end = endHeading?.index ?? source.length;
  return source.slice(startHeading.index, end).trim();
}

function createPresentationDeck(deck: PresentationDeck): PresentationDeck {
  return deck;
}

export function createPresentationSlides(
  deck: PresentationDeck,
): PresentationSlide[] {
  return deck.slides.map((definition) => {
    const resolvedSceneLayout = definition.sceneLayout ?? deck.sceneLayout ?? "world-grid";
    const resolvedTopologyLayout = definition.topologyLayout ?? deck.topologyLayout ?? "ring";
    const resolvedConnectorRouting = definition.connectorRouting ?? deck.connectorRouting;
    const resolvedSpiralDirection = definition.spiralDirection ?? deck.spiralDirection ?? "W";
    const resolvedFanDirection = definition.fanDirection ?? deck.fanDirection ?? "E";
    const resolvedSubtitle = definition.subtitle ?? "";
    const resolvedSummary = definition.summary ?? "";
    const resolvedStatus = definition.status ?? "ready";
    const resolvedRoute = definition.route ?? "/";
    const resolvedRole = definition.role ?? "node";

    const topology = definition.topology
      ? {
          ...definition.topology,
          nodes: definition.topology.nodes.map((node) => ({ ...node })),
          relationships: (definition.topology.relationships ?? []).map((relationship) => ({ ...relationship })),
          connectorRouting: definition.topology.connectorRouting ?? resolvedConnectorRouting,
        }
      : createSlideTopology({
          ...definition,
          sceneLayout: resolvedSceneLayout,
          topologyLayout: resolvedTopologyLayout,
          connectorRouting: resolvedConnectorRouting,
          spiralDirection: resolvedSpiralDirection,
          fanDirection: resolvedFanDirection,
        });
    const records: PresentationRecord[] = definition.records
      ? definition.records.map((record) => ({
          ...record,
          subtitle: record.subtitle ?? "",
          summary: record.summary ?? "",
          status: record.status ?? "",
          route: record.route ?? "/",
          role: record.role ?? "node",
          content: record.content ?? "",
        }))
      : topology.nodes.map((node) => ({
          id: node.id,
          presetId: definition.id,
          eyebrow: definition.title,
          title: node.label,
          subtitle: node.subtitle ?? "Topology node",
          summary: node.variant === "root"
            ? resolvedSummary
            : node.variant === "anchor"
              ? node.label + " organizes a related branch of this presentation."
              : node.label + " is a child node in the " + definition.title + " presentation.",
          status: node.variant === "root" ? resolvedStatus : "ready",
          route: resolvedRoute,
          role: node.variant === "root" ? "root" : node.variant === "anchor" ? "anchor" : "node",
          content: getNodeContent(
            definition.content ?? "",
            node.label,
            node.variant === "root",
          ),
        }));

    return {
      ...definition,
      subtitle: resolvedSubtitle,
      summary: resolvedSummary,
      status: resolvedStatus,
      route: resolvedRoute,
      role: resolvedRole,
      sceneLayout: resolvedSceneLayout,
      topologyLayout: resolvedTopologyLayout,
      connectorRouting: resolvedConnectorRouting,
      spiralDirection: resolvedSpiralDirection,
      fanDirection: resolvedFanDirection,
      topology,
      records,
    };
  });
}